input.command:
cat > tmp/an.mjs <<'EOF'
import fs from 'fs';
const [,,name,mode]=process.argv;
const W=320,H=180,FS=W*H*3;
const b=fs.readFileSync(`tmp/${name}.raw`);
const n=b.length/FS;
const isRed=(r,g,bl)=>r>170&&g<80&&bl<80;
const isYel=(r,g,bl)=>r>200&&g>160&&bl<80;
const isOr=(r,g,bl)=>r>220&&g>110&&g<170&&bl<60;
const f=mode==='red'?isRed:mode==='yel'?isYel:isOr;
for(let i=0;i<n;i++){let c=0,sx=0,sy=0,x0=1e9,x1=-1,y0=1e9,y1=-1;const o=i*FS;
for(let y=0;y<H;y++)for(let x=0;x<W;x++){const p=o+(y*W+x)*3;if(f(b[p],b[p+1],b[p+2])){c++;sx+=x;sy+=y;if(x<x0)x0=x;if(x>x1)x1=x;if(y<y0)y0=y;if(y>y1)y1=y;}}
console.log(i,c,c?(sx/c).toFixed(1):'-',c?(sy/c).toFixed(1):'-',x0,x1,y0,y1);}
EOF
for t in "jump-count red" "stroke-rate yel" "cone-touches red" "shot-outcomes or"; do set -- $t; node tmp/an.mjs $1 $2 > tmp/$1.txt; done; wc -l tmp/*.txt
awk '{print $1,$8}' tmp/jump-count.txt | awk 'BEGIN{p=0}{if($2<149){if(!p){print "up",$1};p=1}else{if(p)print "down",$1;p=0}}'

